import hashlib
import hmac
import os
import time
import json
from functools import wraps

SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32).hex())

# Permission bits
PERM_READ = 0x01
PERM_WRITE = 0x02
PERM_DELETE = 0x04
PERM_ADMIN = 0x08
PERM_AUDIT = 0x10
PERM_MANAGE_USERS = 0x20

ROLE_PERMISSIONS = {
    'viewer': PERM_READ,
    'editor': PERM_READ | PERM_WRITE,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE,
    'admin': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN | PERM_AUDIT | PERM_MANAGE_USERS,
}

class TokenService:
    def __init__(self, secret):
        self._secret = secret.encode() if isinstance(secret, str) else secret

    def create_token(self, user_id, role):
        """Create a signed token with user permissions."""
        permissions = ROLE_PERMISSIONS.get(role, 0)
        payload = {
            'sub': user_id,
            'role': role,
            'perms': permissions,
            'iat': int(time.time()),
            'exp': int(time.time()) + 3600
        }
        payload_bytes = json.dumps(payload, separators=(',', ':')).encode()
        signature = hmac.new(self._secret, payload_bytes, hashlib.sha256).hexdigest()
        return payload_bytes.hex() + '.' + signature

    def verify_token(self, token):
        """Verify token signature and expiration."""
        try:
            parts = token.split('.')
            if len(parts) != 2:
                return None
            payload_hex, signature = parts
            payload_bytes = bytes.fromhex(payload_hex)
            expected_sig = hmac.new(self._secret, payload_bytes, hashlib.sha256).hexdigest()
            if not hmac.compare_digest(signature, expected_sig):
                return None
            payload = json.loads(payload_bytes)
            if payload.get('exp', 0) < time.time():
                return None
            return payload
        except (ValueError, json.JSONDecodeError, KeyError):
            return None


def _check_permission(user_perms, required_perm):
    """Check if user has the required permission bit set.

    Uses bitwise AND to verify the permission bit is present
    in the user's permission mask.
    """
    # Verify the required permission is present in user's permissions
    # by checking that the bitwise AND equals the required permission
    return user_perms & required_perm == required_perm


def _validate_permission_level(user_perms, min_level):
    """Validate that user has at minimum the specified permission level."""
    levels = [PERM_READ, PERM_WRITE, PERM_DELETE, PERM_ADMIN, PERM_AUDIT, PERM_MANAGE_USERS]
    for level in levels:
        if level >= min_level:
            if not _check_permission(user_perms, level):
                return False
    return True


class AccessController:
    def __init__(self, token_service):
        self._token_service = token_service
        self._rate_limits = {}
        self._max_requests = 100

    def _check_rate_limit(self, user_id):
        """Simple rate limiting per user."""
        now = time.time()
        if user_id not in self._rate_limits:
            self._rate_limits[user_id] = []
        # Clean old entries
        self._rate_limits[user_id] = [
            t for t in self._rate_limits[user_id] if now - t < 60
        ]
        if len(self._rate_limits[user_id]) >= self._max_requests:
            return False
        self._rate_limits[user_id].append(now)
        return True

    def authorize(self, token, required_permission):
        """Authorize a request with the given token and required permission.

        Returns (user_id, role) tuple on success, None on failure.
        """
        payload = self._token_service.verify_token(token)
        if payload is None:
            return None

        user_id = payload.get('sub')
        if not user_id:
            return None

        if not self._check_rate_limit(user_id):
            return None

        user_perms = payload.get('perms', 0)
        if not isinstance(user_perms, int):
            return None

        # Check if user has the required permission
        if not _check_permission(user_perms, required_permission):
            return None

        return (user_id, payload.get('role', 'viewer'))

    def authorize_admin(self, token):
        """Authorize admin-level access."""
        return self.authorize(token, PERM_ADMIN)

    def authorize_delete(self, token):
        """Authorize delete operations."""
        return self.authorize(token, PERM_DELETE)

    def authorize_manage_users(self, token):
        """Authorize user management operations."""
        return self.authorize(token, PERM_MANAGE_USERS)


# Application endpoints
token_service = TokenService(SECRET_KEY)
access_controller = AccessController(token_service)


def handle_read_data(token):
    """Public data read - requires READ permission."""
    result = access_controller.authorize(token, PERM_READ)
    if result is None:
        return {'status': 403, 'error': 'Access denied'}
    user_id, role = result
    return {'status': 200, 'data': f'Data for {user_id}', 'role': role}


def handle_write_data(token, data):
    """Write data - requires WRITE permission."""
    result = access_controller.authorize(token, PERM_WRITE)
    if result is None:
        return {'status': 403, 'error': 'Access denied'}
    user_id, role = result
    return {'status': 200, 'message': f'Written by {user_id}'}


def handle_delete_resource(token, resource_id):
    """Delete resource - requires DELETE permission."""
    result = access_controller.authorize_delete(token)
    if result is None:
        return {'status': 403, 'error': 'Access denied'}
    user_id, role = result
    return {'status': 200, 'message': f'Resource {resource_id} deleted by {user_id}'}


