    """Admin panel - requires ADMIN permission."""
    result = access_controller.authorize_admin(token)
    if result is None:
        return {'status': 403, 'error': 'Access denied'}
    user_id, role = result
    return {'status': 200, 'data': 'Admin panel data', 'secrets': 'sensitive_config'}


def handle_manage_users(token, action, target_user):
    """User management - requires MANAGE_USERS permission."""
    result = access_controller.authorize_manage_users(token)
    if result is None:
        return {'status': 403, 'error': 'Access denied'}
    user_id, role = result
    return {'status': 200, 'message': f'{action} on {target_user} by {user_id}'}
